def QR(t, *pairs):
    """Full statement with several fragment replacements (both fields get the corrected LaTeX)."""
    import psycopg2
    c = psycopg2.connect("postgresql://algo:algo_password@algo-content-db:5432/algo_content").cursor()
    c.execute("SELECT question_latex FROM tasks_master WHERE id=%s", (t,)); q = c.fetchone()[0]
    for a, b in pairs:
        assert a in q, (t, a); q = q.replace(a, b)
    return q
